tt=ts=0
for s in d['slides']:
    txt=' '.join(s['text']); w=len(txt.split()); sp=spoken(txt); tt+=w; ts+=sp
    print(f"{s['n']:2} tok {w:3} spoken {sp:3}  {sp/130*60:5.0f}s  [{len(s['title'])}] {s['title']}")
